290	// loadMemoRelations loads relations for a single memo and converts them to API format.
291	func (s *APIV1Service) loadMemoRelations(ctx context.Context, memo *store.Memo) ([]*v1pb.MemoRelation, error) {
292		relationMap, err := s.batchConvertMemoRelations(ctx, []*store.Memo{memo}, true)
293		if err != nil {
294			return nil, err
295		}
296		return relationMap[memo.ID], nil
297	}
