13	// suppressMentionKey is a context key used to suppress mention notification side effects
14	// when CreateMemo is called internally from CreateMemoComment.
15	type suppressMentionKey struct{}
16	
17	func withSuppressMentionNotifications(ctx context.Context) context.Context {
18		return context.WithValue(ctx, suppressMentionKey{}, true)
19	}
